let systemCredentials = undefined;

function ensureModuleLoaded() {
    if (!systemCredentials) {
        systemCredentials = require("../build/Release/systemCredentials.node");
    }
}

function validateArgument(val, name) {
    if (!val || typeof val !== "string") {
        throw new Error(`Parameter '${name}' must be a non-empty string.`);
    }
}

module.exports.getPassword = (service, account) => {
    ensureModuleLoaded();

    validateArgument(service, "service");
    validateArgument(account, "account");

    return systemCredentials.getPassword(service, account);
};

module.exports.setPassword = (service, account, password) => {
    ensureModuleLoaded();

    validateArgument(service, "service");
    validateArgument(account, "account");
    validateArgument(password, "password");

    return systemCredentials.setPassword(service, account, password);
}

module.exports.setPasswordWithTrustedApp = (service, account, appPath, descriptor, password) => {
    ensureModuleLoaded();

    validateArgument(service, "service");
    validateArgument(account, "account");
    validateArgument(appPath, "appPath");
    validateArgument(descriptor, "descriptor");
    validateArgument(password, "password");

    return systemCredentials.setPasswordWithTrustedApp(service, account, appPath, descriptor, password);
}

module.exports.deletePassword = (service, account) => {
    ensureModuleLoaded();

    validateArgument(service, "service");
    validateArgument(account, "account");

    return systemCredentials.deletePassword(service, account);
}
